begin;
select no_plan();
select has_table('public','cms_revision_media','Historical resource references have an index table');
select ok(not exists(select 1 from pg_proc where oid in ('public.internal_cms_asset_usage(uuid,uuid)'::regprocedure,'public.internal_cms_asset_transition(uuid,uuid,integer,text)'::regprocedure,'public.internal_cms_asset_delete_finalize(uuid,uuid,integer)'::regprocedure) and prosrc like '%cross join lateral public.internal_cms_document_media_placements(revision.document)%'),'Resource inspection and deletion do not parse every historical document');
insert into auth.users(id,email) values ('98000000-0000-4000-8000-000000000001','media-index@example.invalid');
insert into public.profiles(id,role,account_enabled,must_change_password) values ('98000000-0000-4000-8000-000000000001','owner',true,false);
insert into public.cms_assets(id,bucket,path,name,alt,mime,bytes,archived,version) values ('98000000-0000-4000-8000-000000000002','cms-library','images/index-test.webp','index-test','', 'image/webp',100,true,0);
insert into public.cms_revisions(revision,document,fingerprint) values (98000001,'{"presentation":{"images":{"one":{"ref":{"bucket":"cms-library","path":"images/index-test.webp"}},"two":{"ref":{"bucket":"cms-library","path":"images/index-test.webp"}}}}}','index-test');
select is((public.internal_cms_asset_usage('98000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000002')->>'historyReferences')::int,2,'Index counts placements, not only revisions');
select is((select reference_count::int from public.cms_revision_media where revision=98000001),2,'Repeated file placements are compacted without losing counts');
select lives_ok($$select public.internal_cms_asset_transition('98000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000002',0,'trash')$$,'Historical-only file may enter recoverable trash');
select throws_ok($$select public.internal_cms_asset_transition('98000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000002',1,'delete')$$,'23514',null,'History still blocks permanent deletion');
update public.cms_revisions set document='{}' where revision=98000001;
select is((select count(*)::int from public.cms_revision_media where revision=98000001),0,'Changed revision removes stale references');
update public.cms_revisions set document='{"photos":{"person":"person/photo.webp"}}' where revision=98000001;
select is((select path from public.cms_revision_media where revision=98000001),'person/photo.webp','Changed revision indexes new references');
delete from public.cms_revisions where revision=98000001;
select is((select count(*)::int from public.cms_revision_media where revision=98000001),0,'Retention deletion cascades to the index');
select ok((select relrowsecurity from pg_class where oid='public.cms_revision_media'::regclass),'Reference index has RLS');
set local role anon;
select throws_ok($$select * from public.cms_revision_media$$,'42501',null,'Anonymous clients cannot enumerate historical resources');
reset role;
set local role authenticated;
select throws_ok($$select * from public.cms_revision_media$$,'42501',null,'Browser sessions cannot bypass owner RPC');
reset role;
select * from finish();
rollback;
